gajv(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634 \u062e\u0648\u062f\u0631\u0648"},
gasj(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634"},
gajw(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634 \u062e\u0648\u062f\u0631\u0648"},
gL9(){return"\u062a\u063a\u06cc\u06cc\u0631 \u0645\u062f\u0644"},
gaju(){return"\u0645\u062f\u0644 \u062f\u0644\u062e\u0648\u0627\u0647 (\u0628\u062f\u0648\u0646 \u0628\u0633\u062a\u0647 \u06a9\u0627\u062a\u0627\u0644\u0648\u06af)"},
gajr(){return"\u0627\u06cc\u0646 \u062e\u0648\u062f\u0631\u0648 \u0631\u0627 \u062e\u0648\u062f\u062a\u0627\u0646 \u0627\u0641\u0632\u0648\u062f\u0647\u200c\u0627\u06cc\u062f\u061b \u0645\u062f\u0644 \u0648 \u0633\u0627\u0632\u0646\u062f\u0647 \u0631\u0627 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0622\u0632\u0627\u062f\u0627\u0646\u0647 \u0628\u0646\u0648\u06cc\u0633\u06cc\u062f."},
gajq(){return"\u0645\u062f\u0644 \u0627\u0632 \u06a9\u0627\u062a\u0627\u0644\u0648\u06af \u0622\u0645\u062f\u0647 \u0627\u0633\u062a. \u0646\u0627\u0645 \u062f\u0644\u062e\u0648\u0627\u0647\u060c \u0641\u0642\u0637 \u0639\u0646\u0648\u0627\u0646 \u0646\u0645\u0627\u06cc\u0634\u06cc \u0631\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0645\u06cc\u200c\u062f\u0647\u062f."},
gajs(){return"\u0630\u062e\u06cc\u0631\u0647 \u062a\u063a\u06cc\u06cc\u0631\u0627\u062a"},
gajt(){return"\u062a\u063a\u06cc\u06cc\u0631\u0627\u062a \u0630\u062e\u06cc\u0631\u0647 \u0634\u062f"},
ga1D(){return"\u0638\u0627\u0647\u0631 \u0648 \u0632\u0628\u0627\u0646"},
ga1F(){return"\u0646\u0648\u0634\u062a\u0647\u200c\u0647\u0627"},
ga1E(){return"\u0635\u062f\u0627"},
ga1C(){return"\u0647\u0648\u0634 \u0645\u0635\u0646\u0648\u0639\u06cc"},
garl(){return"\u0645\u062a\u0646 \u067e\u0631\u0631\u0646\u06af"},
garm(){return"\u0647\u0645\u0647\u0654 \u0646\u0648\u0634\u062a\u0647\u200c\u0647\u0627\u06cc \u0628\u0631\u0646\u0627\u0645\u0647 \u0631\u0627 \u0636\u062e\u06cc\u0645\u200c\u062a\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f."},
garo(){return"\u0627\u0646\u062f\u0627\u0632\u0647\u0654 \u0646\u0648\u0634\u062a\u0647"},
garn(){return"\u0631\u0648\u063a\u0646 \u0645\u0648\u062a\u0648\u0631 \u0631\u0627 \u0637\u0628\u0642 \u062f\u0641\u062a\u0631\u0686\u0647\u060c \u0647\u0631 \u06f5\u066c\u06f0\u06f0\u06f0 \u062a\u0627 \u06f1\u06f0\u066c\u06f0\u06f0\u06f0 \u06a9\u06cc\u0644\u0648\u0645\u062a\u0631 \u062a\u0639\u0648\u06cc\u0636 \u06a9\u0646\u06cc\u062f. Oil change: every 5,000 km."},
ga_z(){return"\u0628\u0627\u0632\u0646\u0634\u0627\u0646\u06cc \u0627\u0646\u062f\u0627\u0632\u0647 \u0648 \u0636\u062e\u0627\u0645\u062a"},
ga1S(){return"\u0635\u062f\u0627\u06cc \u0631\u0648\u0634\u0646 \u0634\u062f\u0646 \u0645\u0648\u062a\u0648\u0631"},
ga1T(){return"\u0647\u0646\u06af\u0627\u0645 \u0632\u0646\u062f\u0647 \u0634\u062f\u0646 \u062e\u0648\u062f\u0631\u0648 \u062f\u0631 \u06af\u0627\u0631\u0627\u0698 \u067e\u062e\u0634 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0628\u0627 \xab\u06a9\u0627\u0647\u0634 \u062d\u0631\u06a9\u062a\xbb \u0628\u06cc\u200c\u0635\u062f\u0627 \u0648 \u0633\u0627\u06a9\u0646 \u0645\u06cc\u200c\u0645\u0627\u0646\u062f."},
gafv(){return"\u0628\u062f\u0648\u0646 \u06a9\u0644\u06cc\u062f \u06cc\u0627 \u0628\u062f\u0648\u0646 \u0627\u06cc\u0646\u062a\u0631\u0646\u062a\u060c \u0645\u06a9\u0627\u0646\u06cc\u06a9 \u0647\u0648\u0634\u0645\u0646\u062f \u0628\u0627 \u0645\u0648\u062a\u0648\u0631 \u0622\u0641\u0644\u0627\u06cc\u0646 \u0648 \u0641\u0642\u0637 \u0628\u0627 \u062f\u0627\u062f\u0647\u200c\u0647\u0627\u06cc \u062e\u0648\u062f\u062a\u0627\u0646 \u067e\u0627\u0633\u062e \u0645\u06cc\u200c\u062f\u0647\u062f."},
gV4(){return"\u0627\u0631\u0627\u0626\u0647\u200c\u062f\u0647\u0646\u062f\u0647"},
gafx(){return"\u062e\u0627\u0645\u0648\u0634 (\u0622\u0641\u0644\u0627\u06cc\u0646)"},
gafw(){return"\u0633\u0641\u0627\u0631\u0634\u06cc"},
gaft(){return"\u0646\u0627\u0645 \u0645\u062f\u0644"},
gaf5(){return"\u0646\u0634\u0627\u0646\u06cc \u067e\u0627\u06cc\u0647 (\u0633\u0627\u0632\u06af\u0627\u0631 \u0628\u0627 OpenAI)"},
gafh(){return"\u06a9\u0644\u06cc\u062f API"},
gafm(){return"\u0630\u062e\u06cc\u0631\u0647\u0654 \u06a9\u0644\u06cc\u062f"},
gafp(){return"\u0622\u0632\u0645\u0627\u06cc\u0634 \u06a9\u0644\u06cc\u062f"},
