gafo(){return"\u06cc\u06a9 \u06a9\u0644\u06cc\u062f \u0631\u0648\u06cc \u0647\u0645\u06cc\u0646 \u062f\u0633\u062a\u06af\u0627\u0647 \u0630\u062e\u06cc\u0631\u0647 \u0634\u062f\u0647 \u0627\u0633\u062a."},
gafi(){return"\u06a9\u0644\u06cc\u062f\u06cc \u0630\u062e\u06cc\u0631\u0647 \u0646\u0634\u062f\u0647 \u0627\u0633\u062a."},
gV3(){return"\u0627\u0628\u062a\u062f\u0627 \u06a9\u0644\u06cc\u062f \u0631\u0627 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f."},
gafn(){return"\u06a9\u0644\u06cc\u062f \u0630\u062e\u06cc\u0631\u0647 \u0634\u062f."},
gafl(){return"\u06a9\u0644\u06cc\u062f \u062d\u0630\u0641 \u0634\u062f."},
gafI(){return"\u06a9\u0644\u06cc\u062f \u06a9\u0627\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f."},
gafj(){return"\u06a9\u0644\u06cc\u062f \u0631\u0645\u0632\u06af\u0630\u0627\u0631\u06cc\u200c\u0634\u062f\u0647 \u0631\u0648\u06cc \u0647\u0645\u06cc\u0646 \u062f\u0633\u062a\u06af\u0627\u0647 \u0645\u06cc\u200c\u0645\u0627\u0646\u062f\u060c \u0647\u0631\u06af\u0632 \u0647\u0645\u06af\u0627\u0645\u200c\u0633\u0627\u0632\u06cc \u06cc\u0627 \u062b\u0628\u062a \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0641\u0642\u0637 \u0628\u0647 \u0627\u0631\u0627\u0626\u0647\u200c\u062f\u0647\u0646\u062f\u0647\u0654 \u0627\u0646\u062a\u062e\u0627\u0628\u06cc \u0634\u0645\u0627 \u0641\u0631\u0633\u062a\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f."},
gafq(){return"\u062f\u0631 \u0646\u0633\u062e\u0647\u0654 \u0648\u0628\u060c \u06a9\u0644\u06cc\u062f \u062f\u0631 \u062d\u0627\u0641\u0638\u0647\u0654 \u0647\u0645\u06cc\u0646 \u0645\u0631\u0648\u0631\u06af\u0631 \u0630\u062e\u06cc\u0631\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0627\u0645\u0646\u06cc\u062a \u0622\u0646 \u0628\u0647 \u0627\u0646\u062f\u0627\u0632\u0647\u0654 \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0627\u0646\u062f\u0631\u0648\u06cc\u062f \u0646\u06cc\u0633\u062a. \u0641\u0642\u0637 \u0631\u0648\u06cc \u062f\u0633\u062a\u06af\u0627\u0647 \u0634\u062e\u0635\u06cc \u062e\u0648\u062f\u062a\u0627\u0646 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u062d\u0630\u0641\u0634 \u06a9\u0646\u06cc\u062f."},
